/**
 * @brief Format performance metric data points for the monitoring system
 * 
 * Formats the metric name and label key-value pairs into a standardized monitoring data point string.
 * The generated format is: metric_name{label_key1="label_value1",label_key2="label_value2",...}
 * If there are no labels, only the metric name is output (no braces).
 *
 * @param metric_name The metric name string
 * @param label_keys Array of label key strings
 * @param label_values Array of label value strings (one-to-one with label_keys)
 * @param label_count Number of label key-value pairs
 * @param metric_output Output buffer; caller must ensure it is large enough
 * 
 * @return On success, the length of the formatted string (excluding '\\0'); on failure, -1.
 */
int format_metric_point(char* metric_name, char** label_keys, char** label_values, int label_count, char* metric_output)
{
    int written;
    int pos = 0;

    /* Input validation */
    if (metric_name == NULL || metric_output == NULL) {
        return -1;
    }
    if (label_count < 0) {
        return -1;
    }
    if (label_count > 0) {
        if (label_keys == NULL || label_values == NULL) {
            return -1;
        }
        /* Validate each label key and value */
        for (int i = 0; i < label_count; i++) {
            if (label_keys[i] == NULL || label_values[i] == NULL) {
                return -1;
            }
        }
    }

    /* No labels: output metric name only */
    if (label_count == 0) {
        written = sprintf(metric_output, "%s", metric_name);
        if (written < 0) {
            return -1;
        }
        return written;
    }

    /* Start with metric name and opening brace */
    written = sprintf(metric_output, "%s{", metric_name);
    if (written < 0) {
        return -1;
    }
    pos += written;

    /* Append label key-value pairs */
    for (int i = 0; i < label_count; i++) {
        if (i > 0) {
            written = sprintf(metric_output + pos, ",");
            if (written < 0) {
                return -1;
            }
            pos += written;
        }
        written = sprintf(metric_output + pos, "%s=\"%s\"", label_keys[i], label_values[i]);
        if (written < 0) {
            return -1;
        }
        pos += written;
    }

    /* Closing brace */
    written = sprintf(metric_output + pos, "}");
    if (written < 0) {
        return -1;
    }
    pos += written;

    /* pos now holds the total length of the formatted string (excluding null terminator) */
    return pos;
}

